// packages/trace-export/src/validateArenaTraceV3.ts
export function validateArenaTraceV3(trace: unknown): ArenaTraceValidationResult {
  const errors: string[] = [];

  // Field-by-field validation
  if (!trace || typeof trace !== ' object') {
    errors.push('Root must be an object');
    return { valid: false, errors };
  }

  const t = trace as any;

  // Required fields
  const requiredFields = ['version', 'episodeId', 'seed', 'envVersion', 'contractVersion', 'runKind', 'initialState', 'events', 'replay', 'terminal'];
  for (const field of requiredFields) {
    if (!(field in t)) {
      errors.push(`Missing required field: ${field}`);
    }
  }

  // Version validation
  if (t.version !== 'v3') {
    errors.push('version must be "v3"');
  }

  // runKind validation
  if (!['live', 'synthetic', 'benchmark'].includes(t.runKind)) {
    errors.push('runKind must be one of: live, synthetic, benchmark');
  }

  // episodeId validation
  if (!t.episodeId || typeof t.episodeId !== 'string' || !t.episodeId.match(/^[a-z0-9-]+-\d+$/)) {
    errors.push('episodeId must be in format "variation-seed"');
  }

  // seed validation
  if (!t .seed || typeof t.seed !== 'number' || t.seed < 0) {
    errors.push('seed must be a positive number');
  }

  // initialState validation
  if (!t.initialState || typeof t.initialState !== 'object') {
    errors.push('initialState must be an object');
 } else {
    // Validate initialState fields
    const stateFields = ['seed', 'episode', 'clock', 'tables', 'orders', 'inventory', 'equipment', 'workers', 'emergency', 'reputation', 'outcomes'];
    for (const field of stateFields) {
      if (!(field in t.initialState)) {
        errors.push(`initialState missing field: ${field}`);
      }
    }
  }

  // events validation
  if (!Array.isArray(t.events)) {
    errors.push('events must be an array');
  } else {
    t.events.forEach((event, index) => {
      if (!event || typeof event !== 'object') {
        errors.push(`event at index ${index} must be an object`);
        return;
      }
      const eventFields = ['tick', 'kind', 'timestamp', 'stateHash', 'actorId', 'text', 'observation', 'round'];
 <fim-middle>    for (const field of eventFields) {
        if (!(field in event)) {
          errors.push(`event at index ${index} missing field: ${field}`);
        }
      }
    });
  }

  // replay validation
  if (!t.replay || typeof t.replay !== ' object') {
    errors.push('replay must be an object');
  } else {
    if (!Array.isArray(t.replay.inputs)) {
      errors.push('replay.inputs must be an array');
    }
    if (!t.replay.terminal || typeof t.replay.terminal !== 'object') {
      errors .push('replay.terminal must be an object');
    }
  }

  // terminal validation
  if (!t.terminal || typeof t.terminal !== 'object') {
    errors.push('terminal must be an object');
  } else {
    const terminalFields = ['status', 'tick', 'reason'];
    for (const field of terminalFields) {
      if (!(field in t.terminal)) {
        errors.push(`terminal missing field: ${field}`);
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors
  };
}
