// restaurant-arena-trace-v3.js
// Full implementation matching the contract in docs/restaurant-arena-trace-contract.md

const fs = require('fs');
const path = require('path');

const TRACE_VERSION = 'restaurant-arena-trace/v3';
const CONTRACT_VERSION = 'v3';

const VALID = Symbol('valid');
const INVALID = Symbol('invalid');

function serializeJson(value, pretty = false, unsorted = false) {
  const replacer = unsorted ? null : (k, v) => v;
  const space = pretty ? 2 : 0;
  return JSON.stringify(value, repl acer, space);
}

function normalizeFloat(obj) {
  if (typeof obj !== 'object' || obj === null) return obj;
  if (Array.isArray(obj)) return obj.map(normalizeFloat);
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (typeof v === 'number') {
       out[k] = v % 1 === 0 ? v : parseFloat(v.toFixed(1));
     } else {
       out[k] = normalizeFloat(v);
     }
  }
  return out;
}

function canonicalJson(obj) {
  return serializeJson (normalizeFloat(obj), false, true);
}

function validateArenaTraceV3(trace) {
  if (!trace || typeof trace !== 'object') return INVALID;
  if (trace.version !== TRACE_VERSION) return INVALID;
  if (trace.contractVersion !== CONTRACT_VERSION) return INVALID;
  if (!trace.episode Id || typeof trace.episodeId !== 'string') return INVALID;
  if (typeof trace.seed !== 'number') return INVALID;
  if (!Array.isArray(trace.events)) return INVALID;
  if (typeof trace.initialState !== 'object') return INVALID;
  if (typeof trace.replay !== 'object') return INVALID;
  if (typeof trace.terminal !== 'object') return INVALID;
  if (typeof trace.deletion !== 'object') return INVALID;

  // Field-by-field checks
  for (const event of trace.events) {
    if (!event || typeof event !== 'object') return INVALID;
    if (typeof event.tick !== 'number') return INVALID;
    if (typeof event.timestamp !== 'string') return INVALID;
    if (!event.type) return INVALID;
  }

  // Terminal status checks
  const { status, tick, reason } = trace.terminal;
  if (!['completed', 'failed', 'abandoned '].includes(status)) return INVALID;
  if (typeof tick !== 'number') return INVALID;
  if (reason && typeof reason !== 'string') return INVALID;

  return VALID;
}

function roundForTick(tick) {
  return Math.floor(tick / 3000);
}

function captureArenaTrace(game, options = {}) {
  const events = game.getRecordedEvents();
  const initialState = game.getInitialState();
  const replay = game.getReplayRecord();
  const terminal = game.getTerminalStatus();
  const state = game.state();

  const trace = {
    version: TRACE_VERSION,
    episodeId: options.ep isodeId ?? state.episode.id,
    ...(options.sessionId ? { sessionId: options.sessionId } : {}),
    seed: state.seed,
    envVersion: 'restaurant-arena/1.0',
    contractVersion: CONTRACT_VERSION,
    runKind: options.runKind || 'live',
    initial State,
    replay,
    terminal,
    deletion: { reason: 'shift-finished' },
    events
  };

  // Merge additionalEvents
  if (options.additionalEvents && Array.isArray(options.additionalEvents)) {
    const merged = [...events];
    for (const ev of options.additionalEvents) {
      const stamped = {
         ...ev,
         round: roundForTick(ev.tick)
       };
       merged.push(stamped);
     }
     trace.events = merged.sort((a, b) => a.tick - b.tick);
