  return trace;
}

function exportTraceJson(trace) {
  const valid = validate ArenaTraceV3(trace);
  if (valid !== VALID) throw new Error('Invalid trace');
  return serializeJson(trace, true, false) + '\n';
}

function exportTraceJsonl(trace) {
