    if (!(key in value)) pushError(errors, `$.${key}`, "is required");
  }
  if ("version" in value && value.version !== TRACE_V3_VERSION) {
    pushError(errors, "$.version", `must be ${TRACE_V3_VERSION}`);
  }
  if ("episodeId" in value) expectArenaId(value.episodeId, "$.episodeId", errors);
  if ("sessionId" in value) expectArenaId(value.sessionId, "$.sessionId", errors);
  if ("seed" in value) expectInteger(value.seed, "$.seed", errors, 0);
  if ("envVersion" in value) expectString(value.envVersion, "$.envVersion", errors, 1);
  if ("contractVersion" in value && value.contractVersion !== TRACE_V3_CONTRACT_VERSION) {
    pushError(errors, "$.contractVersion", `must be ${TRACE_V3_CONTRACT_VERSION}`);
  }
  if ("runKind" in value && !RUN_KINDS.has(value.runKind as string)) {
    pushError(errors, "$.runKind", "must be live, synthetic, or benchmark");
  }
  if ("initialState" in value) validateInitialState(value.initialState, "$.initialState", errors);
  if ("events" in value) {
    if (!Array.isArray(value.events)) pushError(errors, "$.events", "must be an array");
    else value.events.forEach((event, index) => validateEvent(event, `$.events[${index}]`, errors));
  }
  if ("deletion" in value) {
    if (!isRecord(value.deletion)) pushError(errors, "$.deletion", "must be an object");
    else {
      extraKeys(value.deletion, DELETION_KEYS, "$.deletion", errors);
      if (!("requestId" in value.deletion)) pushError(errors, "$.deletion.requestId", "is required");
      else if (value.deletion.requestId !== null) expectArenaId(value.deletion.requestId, "$.deletion.requestId", errors);
      if (!("status" in value.deletion)) pushError(errors, "$.deletion.status", "is required");
      else if (!DELETION_STATUSES.has(value.deletion.status as string)) {
        pushError(errors, "$.deletion.status", "must be retained, requested, or deleted");
      }
    }
  }
  if ("replay" in value) {
    if (!isRecord(value.replay)) pushError(errors, "$.replay", "must be an object");
    else {
      extraKeys(value.replay, REPLAY_KEYS, "$.replay", errors);
      if (!("variation" in value.replay)) pushError(errors, "$.replay.variation", "is required");
      else if (!VARIATIONS.has(value.replay.variation as string)) {
        pushError(errors, "$.replay.variation", "must be a published variation");
      }
      if (!("inputs" in value.replay)) pushError(errors, "$.replay.inputs", "is required");
      else if (!Array.isArray(value.replay.inputs)) pushError(errors, "$.replay.inputs", "must be an array");
      else {
        value.replay.inputs.forEach((input, index) => validateReplayInput(input, `$.replay.inputs[${index}]`, errors));
      }
      if (!("finalStateHash" in value.replay)) pushError(errors, "$.replay.finalStateHash", "is required");
      else expectStateHash(value.replay.finalStateHash, "$.replay.finalStateHash", errors);
      if ("finalRestaurantStateHash" in value.replay) {
        expectStateHash(value.replay.finalRestaurantStateHash, "$.replay.finalRestaurantStateHash", errors);
      }
    }
  }
  if ("terminal" in value) {
    if (!isRecord(value.terminal)) pushError(errors, "$.terminal", "must be an object");
    else {
      extraKeys(value.terminal, TERMINAL_KEYS, "$.terminal", errors);
      if (!("status" in value.terminal)) pushError(errors, "$.terminal.status", "is required");
      else if (!TERMINAL_STATUSES.has(value.terminal.status as string)) {
        pushError(errors, "$.terminal.status", "must be active, completed, or abandoned");
      }
      if (!("tick" in value.terminal)) pushError(errors, "$.terminal.tick", "is required");
      else expectInteger(value.terminal.tick, "$.terminal.tick", errors, 0);
      if (!("reason" in value.terminal)) pushError(errors, "$.terminal.reason", "is required");
      else if (value.terminal.reason !== null && typeof value.terminal.reason !== "string") {
        pushError(errors, "$.terminal.reason", "must be a string or null");
      }
    }
  }
  return { valid: errors.length === 0, errors };
}

