function cloneJson<T>(value: T): T {
  return structuredClone(value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function stampEventTimestamp(event: TraceV3Event, startMs: number): TraceV3Event {
  return { ...event, timestamp: new Date(startMs + event.tick * 3000).toISOString() };
}

/**
 * Capture a restaurant-arena-trace-v3 record from a running game.
 * Overlay callers import this helper directly.
 */
export function captureArenaTrace(game: ArenaTraceSource, options: TraceCaptureOptions): RestaurantArenaTraceV3 {
  if (!options || !RUN_KINDS.has(options.runKind)) {
    throw new TypeError('captureArenaTrace requires runKind of "live", "synthetic", or "benchmark"');
  }

  const replay = cloneJson(game.getReplayRecord());
  let events = cloneJson(options.events ?? game.getRecordedEvents());
  if (options.additionalEvents?.length) {
    const extra = options.additionalEvents.map((event) => ({
      ...cloneJson(event),
      round: roundForTick(event.tick),
    }));
    events = [...events, ...extra].sort((left, right) => left.tick - right.tick);
  }
  if (options.startTime) {
    const startMs = Date.parse(options.startTime);
    if (Number.isNaN(startMs)) throw new TypeError("startTime must be an ISO-8601 timestamp");
    events = events.map((event) => stampEventTimestamp(event, startMs));
  }

  const state = game.state();
  const trace: RestaurantArenaTraceV3 = {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? state.episode.id,
    seed: state.seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState: cloneJson(game.getInitialState()),
    events,
    deletion: {
      requestId: options.deletion?.requestId !== undefined ? options.deletion.requestId : null,
      status: options.deletion?.status ?? "retained",
    },
    replay,
    terminal: cloneJson(game.getTerminalStatus()),
  };
  if (options.sessionId !== undefined) trace.sessionId = options.sessionId;
  return trace;
}

export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
