export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  const lines = [serializeJson(header, false, false) ?? "null"];
  for (const event of events) lines.push(serializeJson(event, false, false) ?? "null");
  return `${lines.join("\n")}\n`;
}

export interface ArenaTraceValidationResult {
  valid: boolean;
  errors: string[];
}

function pushError(errors: string[], path: string, message: string): void {
  errors.push(`${path}: ${message}`);
}

function extraKeys(record: Record<string, unknown>, allowed: Set<string>, path: string, errors: string[]): void {
  for (const key of Object.keys(record)) {
    if (!allowed.has(key)) pushError(errors, path, `additional property '${key}' is not allowed`);
  }
}

function expectInteger(value: unknown, path: string, errors: string[], minimum?: number): void {
  if (typeof value !== "number" || !Number.isInteger(value) || !Number.isFinite(value)) {
    pushError(errors, path, "must be an integer");
    return;
  }
  if (minimum !== undefined && value < minimum) pushError(errors, path, `must be >= ${minimum}`);
}

function expectNumber(value: unknown, path: string, errors: string[], minimum?: number, maximum?: number): void {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    pushError(errors, path, "must be a number");
    return;
  }
  if (minimum !== undefined && value < minimum) pushError(errors, path, `must be >= ${minimum}`);
  if (maximum !== undefined && value > maximum) pushError(errors, path, `must be <= ${maximum}`);
}

function expectString(value: unknown, path: string, errors: string[], minLength = 0): value is string {
  if (typeof value !== "string") {
    pushError(errors, path, "must be a string");
    return false;
  }
  if (value.length < minLength) pushError(errors, path, `must be at least ${minLength} character(s)`);
  return true;
}

function expectArenaId(value: unknown, path: string, errors: string[]): void {
  if (!expectString(value, path, errors, 1)) return;
  if (value.length > 64 || !ARENA_ID.test(value)) pushError(errors, path, "must be an arena id");
}

function expectStateHash(value: unknown, path: string, errors: string[]): void {
  if (!expectString(value, path, errors, 1)) return;
  if (!STATE_HASH.test(value)) pushError(errors, path, "must match sha256:<64 hex chars>");
}

function expectDateTime(value: unknown, path: string, errors: string[]): void {
  if (!expectString(value, path, errors, 1)) return;
  if (!DATE_TIME.test(value) || Number.isNaN(Date.parse(value))) pushError(errors, path, "must be an ISO-8601 date-time");
}

function expectNullableString(value: unknown, path: string, errors: string[]): void {
  if (value !== null && typeof value !== "string") pushError(errors, path, "must be a string or null");
}

function expectObjectOrNull(value: unknown, path: string, errors: string[]): void {
  if (value !== null && !isRecord(value)) pushError(errors, path, "must be an object or null");
}

function validateModel(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, MODEL_KEYS, path, errors);
  if (!("provider" in value)) pushError(errors, `${path}.provider`, "is required");
  else expectString(value.provider, `${path}.provider`, errors, 1);
