  if ("tool" in value && !ACTION_TOOLS.has(value.tool as string)) pushError(errors, `${path}.tool`, "must be a known tool");
  if ("arguments" in value && !isRecord(value.arguments)) pushError(errors, `${path}.arguments`, "must be an object");
  if ("tick" in value) expectInteger(value.tick, `${path}.tick`, errors, 0);
  if ("timestamp" in value) expectDateTime(value.timestamp, `${path}.timestamp`, errors);
  if ("requestId" in value) expectArenaId(value.requestId, `${path}.requestId`, errors);
  if ("idempotencyKey" in value) {
    if (!expectString(value.idempotencyKey, `${path}.idempotencyKey`, errors, 1)) {
      /* already recorded */
