function validateInitialState(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, STATE_KEYS, path, errors);
  for (const key of ["version", "seed", "episode", "clock", "tables", "orders", "inventory", "equipment", "workers", "reputation", "outcomes"] as const) {
    if (!(key in value)) pushError(errors, `${path}.${key}`, "is required");
  }
  if ("version" in value && value.version !== "restaurant-arena/v1") {
    pushError(errors, `${path}.version`, "must be restaurant-arena/v1");
  }
  if ("seed" in value) expectInteger(value.seed, `${path}.seed`, errors, 0);
  if ("episode" in value) validateEpisode(value.episode, `${path}.episode`, errors);
  if ("clock" in value) validateClock(value.clock, `${path}.clock`, errors);
  if ("tables" in value) {
    if (!Array.isArray(value.tables)) pushError(errors, `${path}.tables`, "must be an array");
    else {
      value.tables.forEach((table, index) => {
        const tablePath = `${path}.tables[${index}]`;
        if (!isRecord(table)) {
          pushError(errors, tablePath, "must be an object");
          return;
        }
        extraKeys(table, TABLE_KEYS, tablePath, errors);
        if (!("id" in table)) pushError(errors, `${tablePath}.id`, "is required");
        else expectArenaId(table.id, `${tablePath}.id`, errors);
        if (!("seats" in table)) pushError(errors, `${tablePath}.seats`, "is required");
        else expectInteger(table.seats, `${tablePath}.seats`, errors, 1);
        if (!("status" in table)) pushError(errors, `${tablePath}.status`, "is required");
        else if (!TABLE_STATUSES.has(table.status as string)) pushError(errors, `${tablePath}.status`, "must be empty or occupied");
        if ("orderId" in table) expectArenaId(table.orderId, `${tablePath}.orderId`, errors);
      });
    }
  }
  if ("orders" in value) {
    if (!Array.isArray(value.orders)) pushError(errors, `${path}.orders`, "must be an array");
    else {
      value.orders.forEach((order, index) => {
        const orderPath = `${path}.orders[${index}]`;
        if (!isRecord(order)) {
          pushError(errors, orderPath, "must be an object");
          return;
        }
        extraKeys(order, ORDER_KEYS, orderPath, errors);
        if (!("id" in order)) pushError(errors, `${orderPath}.id`, "is required");
        else expectArenaId(order.id, `${orderPath}.id`, errors);
        if ("tableId" in order) expectArenaId(order.tableId, `${orderPath}.tableId`, errors);
        if (!("items" in order)) pushError(errors, `${orderPath}.items`, "is required");
        else if (!Array.isArray(order.items)) pushError(errors, `${orderPath}.items`, "must be an array");
        else {
          order.items.forEach((item, itemIndex) => {
            if (typeof item !== "string" || item.length < 1) {
              pushError(errors, `${orderPath}.items[${itemIndex}]`, "must be a non-empty string");
            }
          });
        }
        if (!("status" in order)) pushError(errors, `${orderPath}.status`, "is required");
        else if (!ORDER_STATUSES.has(order.status as string)) pushError(errors, `${orderPath}.status`, "must be an order status");
        if ("allergy" in order) expectString(order.allergy, `${orderPath}.allergy`, errors, 1);
        if (!("priority" in order)) pushError(errors, `${orderPath}.priority`, "is required");
        else if (order.priority !== "normal" && order.priority !== "high") {
          pushError(errors, `${orderPath}.priority`, "must be normal or high");
        }
      });
    }
  }
  if ("inventory" in value) {
    if (!isRecord(value.inventory)) pushError(errors, `${path}.inventory`, "must be an object");
    else {
      for (const [item, count] of Object.entries(value.inventory)) {
        expectInteger(count, `${path}.inventory.${item}`, errors, 0);
      }
    }
  }
  if ("equipment" in value) {
    if (!Array.isArray(value.equipment)) pushError(errors, `${path}.equipment`, "must be an array");
    else {
      value.equipment.forEach((item, index) => {
        const itemPath = `${path}.equipment[${index}]`;
        if (!isRecord(item)) {
          pushError(errors, itemPath, "must be an object");
          return;
        }
        extraKeys(item, EQUIPMENT_KEYS, itemPath, errors);
        if (!("id" in item)) pushError(errors, `${itemPath}.id`, "is required");
        else expectArenaId(item.id, `${itemPath}.id`, errors);
        if (!("kind" in item)) pushError(errors, `${itemPath}.kind`, "is required");
        else if (!EQUIPMENT_KINDS.has(item.kind as string)) pushError(errors, `${itemPath}.kind`, "must be an equipment kind");
        if (!("status" in item)) pushError(errors, `${itemPath}.status`, "is required");
        else if (!EQUIPMENT_STATUSES.has(item.status as string)) {
          pushError(errors, `${itemPath}.status`, "must be an equipment status");
        }
        if ("safetyThreshold" in item) expectNumber(item.safetyThreshold, `${itemPath}.safetyThreshold`, errors);
        if ("reading" in item) expectNumber(item.reading, `${itemPath}.reading`, errors);
      });
    }
  }
  if ("workers" in value) {
    if (!Array.isArray(value.workers)) pushError(errors, `${path}.workers`, "must be an array");
    else {
      value.workers.forEach((worker, index) => {
        const workerPath = `${path}.workers[${index}]`;
        if (!isRecord(worker)) {
          pushError(errors, workerPath, "must be an object");
          return;
        }
        extraKeys(worker, WORKER_KEYS, workerPath, errors);
        if (!("id" in worker)) pushError(errors, `${workerPath}.id`, "is required");
        else expectArenaId(worker.id, `${workerPath}.id`, errors);
        if (!("role" in worker)) pushError(errors, `${workerPath}.role`, "is required");
        else if (!TRACE_ROLES.has(worker.role as string)) pushError(errors, `${workerPath}.role`, "must be a staff role");
        if (!("load" in worker)) pushError(errors, `${workerPath}.load`, "is required");
        else expectNumber(worker.load, `${workerPath}.load`, errors, 0, 1);
        if (!("location" in worker)) pushError(errors, `${workerPath}.location`, "is required");
        else if (!WORKER_LOCATIONS.has(worker.location as string)) {
          pushError(errors, `${workerPath}.location`, "must be a worker location");
        }
        if ("lastAction" in worker) expectString(worker.lastAction, `${workerPath}.lastAction`, errors);
      });
    }
  }
  if ("emergency" in value) {
    if (!isRecord(value.emergency)) {
      pushError(errors, `${path}.emergency`, "must be an object");
    } else {
      extraKeys(value.emergency, EMERGENCY_KEYS, `${path}.emergency`, errors);
      if (!("kind" in value.emergency)) pushError(errors, `${path}.emergency.kind`, "is required");
      else if (value.emergency.kind !== "oven_failure") pushError(errors, `${path}.emergency.kind`, "must be oven_failure");
      if (!("active" in value.emergency)) pushError(errors, `${path}.emergency.active`, "is required");
      else if (typeof value.emergency.active !== "boolean") pushError(errors, `${path}.emergency.active`, "must be a boolean");
      if (!("startedAt" in value.emergency)) pushError(errors, `${path}.emergency.startedAt`, "is required");
      else expectInteger(value.emergency.startedAt, `${path}.emergency.startedAt`, errors, 0);
    }
  }
  if ("reputation" in value) expectNumber(value.reputation, `${path}.reputation`, errors, 0, 100);
  if ("outcomes" in value) {
    if (!isRecord(value.outcomes)) {
      pushError(errors, `${path}.outcomes`, "must be an object");
    } else {
      extraKeys(value.outcomes, OUTCOME_KEYS, `${path}.outcomes`, errors);
      for (const key of OUTCOME_KEYS) {
        if (!(key in value.outcomes)) pushError(errors, `${path}.outcomes.${key}`, "is required");
      }
      if ("cash" in value.outcomes) expectNumber(value.outcomes.cash, `${path}.outcomes.cash`, errors, 0);
      if ("satisfaction" in value.outcomes) expectNumber(value.outcomes.satisfaction, `${path}.outcomes.satisfaction`, errors, 0, 1);
      if ("waste" in value.outcomes) expectNumber(value.outcomes.waste, `${path}.outcomes.waste`, errors, 0);
      if ("waitTime" in value.outcomes) expectNumber(value.outcomes.waitTime, `${path}.outcomes.waitTime`, errors, 0);
      if ("completed" in value.outcomes) expectInteger(value.outcomes.completed, `${path}.outcomes.completed`, errors, 0);
      if ("safeOrders" in value.outcomes) expectInteger(value.outcomes.safeOrders, `${path}.outcomes.safeOrders`, errors, 0);
      if ("coordination" in value.outcomes) expectNumber(value.outcomes.coordination, `${path}.outcomes.coordination`, errors, 0, 1);
      if ("correctionUptake" in value.outcomes) {
        expectNumber(value.outcomes.correctionUptake, `${path}.outcomes.correctionUptake`, errors, 0, 1);
      }
    }
  }
}

/**
 * Field-by-field validator for restaurant-arena-trace-v3 records.
 * Overlay callers import this helper directly.
 */
export function validateArenaTraceV3(value: unknown): ArenaTraceValidationResult {
  const errors: string[] = [];
  if (!isRecord(value)) {
    return { valid: false, errors: ["$: must be an object"] };
  }
  extraKeys(value, ROOT_KEYS, "$", errors);
  for (const key of [
    "version",
    "episodeId",
    "seed",
    "envVersion",
    "contractVersion",
    "runKind",
    "initialState",
    "events",
    "deletion",
    "replay",
    "terminal",
  ] as const) {
    if (!(key in value)) pushError(errors, `$.${key}`, "is required");
  }
  if ("version" in value && value.version !== TRACE_V3_VERSION) {
    pushError(errors, "$.version", `must be ${TRACE_V3_VERSION}`);
  }
  if ("episodeId" in value) expectArenaId(value.episodeId, "$.episodeId", errors);
  if ("sessionId" in value) expectArenaId(value.sessionId, "$.sessionId", errors);
  if ("seed" in value) expectInteger(value.seed, "$.seed", errors, 0);
  if ("envVersion" in value) expectString(value.envVersion, "$.envVersion", errors, 1);
  if ("contractVersion" in value && value.contractVersion !== TRACE_V3_CONTRACT_VERSION) {
    pushError(errors, "$.contractVersion", `must be ${TRACE_V3_CONTRACT_VERSION}`);
  }
  if ("runKind" in value && !RUN_KINDS.has(value.runKind as string)) {
    pushError(errors, "$.runKind", "must be live, synthetic, or benchmark");
  }
  if ("initialState" in value) validateInitialState(value.initialState, "$.initialState", errors);
  if ("events" in value) {
    if (!Array.isArray(value.events)) pushError(errors, "$.events", "must be an array");
    else value.events.forEach((event, index) => validateEvent(event, `$.events[${index}]`, errors));
  }
  if ("deletion" in value) {
    if (!isRecord(value.deletion)) pushError(errors, "$.deletion", "must be an object");
    else {
      extraKeys(value.deletion, DELETION_KEYS, "$.deletion", errors);
      if (!("requestId" in value.deletion)) pushError(errors, "$.deletion.requestId", "is required");
      else if (value.deletion.requestId !== null) expectArenaId(value.deletion.requestId, "$.deletion.requestId", errors);
      if (!("status" in value.deletion)) pushError(errors, "$.deletion.status", "is required");
      else if (!DELETION_STATUSES.has(value.deletion.status as string)) {
        pushError(errors, "$.deletion.status", "must be retained, requested, or deleted");
      }
    }
  }
  if ("replay" in value) {
    if (!isRecord(value.replay)) pushError(errors, "$.replay", "must be an object");
    else {
      extraKeys(value.replay, REPLAY_KEYS, "$.replay", errors);
      if (!("variation" in value.replay)) pushError(errors, "$.replay.variation", "is required");
      else if (!VARIATIONS.has(value.replay.variation as string)) {
        pushError(errors, "$.replay.variation", "must be a published variation");
      }
      if (!("inputs" in value.replay)) pushError(errors, "$.replay.inputs", "is required");
      else if (!Array.isArray(value.replay.inputs)) pushError(errors, "$.replay.inputs", "must be an array");
      else {
        value.replay.inputs.forEach((input, index) => validateReplayInput(input, `$.replay.inputs[${index}]`, errors));
      }
      if (!("finalStateHash" in value.replay)) pushError(errors, "$.replay.finalStateHash", "is required");
      else expectStateHash(value.replay.finalStateHash, "$.replay.finalStateHash", errors);
      if ("finalRestaurantStateHash" in value.replay) {
        expectStateHash(value.replay.finalRestaurantStateHash, "$.replay.finalRestaurantStateHash", errors);
      }
    }
  }
  if ("terminal" in value) {
    if (!isRecord(value.terminal)) pushError(errors, "$.terminal", "must be an object");
    else {
      extraKeys(value.terminal, TERMINAL_KEYS, "$.terminal", errors);
      if (!("status" in value.terminal)) pushError(errors, "$.terminal.status", "is required");
      else if (!TERMINAL_STATUSES.has(value.terminal.status as string)) {
