export interface TraceCaptureOptions {
  episodeId?: string;
  sessionId?: string;
  /** Required: live gameplay, synthetic episodes and benchmark episodes must stay distinguishable. */
  runKind: "live" | "synthetic" | "benchmark";
  envVersion?: string;
  startTime?: string;
  deletion?: Partial<{ requestId: string | null; status: "retained" | "requested" | "deleted" }>;
  /** Omit to capture the run's own recorded event journal; pass to replace it wholesale. */
  events?: TraceV3Event[];
  /**
   * Events the caller wants merged into the captured journal alongside the
   * game's own recorded events. Each is stamped with the `round` its `tick`
   * falls in (round r covers ticks 2r-1 and 2r; tick 0 is round 1).
   */
  additionalEvents?: TraceV3Event[];
}

/** The live-game surface capture reads. Kept structural so this module does not import the engine. */
export interface ArenaTraceSource {
  getRecordedEvents(): TraceV3Event[];
  getInitialState(): Record<string, unknown>;
  getReplayRecord(): RestaurantArenaTraceV3["replay"];
  getTerminalStatus(): RestaurantArenaTraceV3["terminal"];
  state(): { seed: number; episode: { id: string } };
}

