function cloneJson<T>(value: T): T {
  return structuredClone(value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function stampEventTimestamp(event: TraceV3Event, startMs: number): TraceV3Event {
  return { ...event, timestamp: new Date(startMs + event.tick * 3000).toISOString() };
}

/**
 * Capture a restaurant-arena-trace-v3 record from a running game.
 * Overlay callers import this helper directly.
 */
export function captureArenaTrace(game: ArenaTraceSource, options: TraceCaptureOptions): RestaurantArenaTraceV3 {
  if (!options || !RUN_KINDS.has(options.runKind)) {
    throw new TypeError('captureArenaTrace requires runKind of "live", "synthetic", or "benchmark"');
  }

  const replay = cloneJson(game.getReplayRecord());
  let events = cloneJson(options.events ?? game.getRecordedEvents());
  if (options.additionalEvents?.length) {
    const extra = options.additionalEvents.map((event) => ({
      ...cloneJson(event),
      round: roundForTick(event.tick),
    }));
    events = [...events, ...extra].sort((left, right) => left.tick - right.tick);
  }
  if (options.startTime) {
    const startMs = Date.parse(options.startTime);
    if (Number.isNaN(startMs)) throw new TypeError("startTime must be an ISO-8601 timestamp");
    events = events.map((event) => stampEventTimestamp(event, startMs));
  }

  const state = game.state();
  const trace: RestaurantArenaTraceV3 = {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? state.episode.id,
    seed: state.seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState: cloneJson(game.getInitialState()),
    events,
    deletion: {
      requestId: options.deletion?.requestId !== undefined ? options.deletion.requestId : null,
      status: options.deletion?.status ?? "retained",
    },
    replay,
    terminal: cloneJson(game.getTerminalStatus()),
  };
  if (options.sessionId !== undefined) trace.sessionId = options.sessionId;
  return trace;
}

export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return `${serializeJson(trace, true, false) ?? "null"}\n`;
}

export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  const lines = [serializeJson(header, false, false) ?? "null"];
  for (const event of events) lines.push(serializeJson(event, false, false) ?? "null");
  return `${lines.join("\n")}\n`;
}

export interface ArenaTraceValidationResult {
  valid: boolean;
  errors: string[];
}

function pushError(errors: string[], path: string, message: string): void {
  errors.push(`${path}: ${message}`);
}

function extraKeys(record: Record<string, unknown>, allowed: Set<string>, path: string, errors: string[]): void {
  for (const key of Object.keys(record)) {
    if (!allowed.has(key)) pushError(errors, path, `additional property '${key}' is not allowed`);
  }
}

function expectInteger(value: unknown, path: string, errors: string[], minimum?: number): void {
  if (typeof value !== "number" || !Number.isInteger(value) || !Number.isFinite(value)) {
    pushError(errors, path, "must be an integer");
    return;
  }
  if (minimum !== undefined && value < minimum) pushError(errors, path, `must be >= ${minimum}`);
}

function expectNumber(value: unknown, path: string, errors: string[], minimum?: number, maximum?: number): void {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    pushError(errors, path, "must be a number");
    return;
  }
  if (minimum !== undefined && value < minimum) pushError(errors, path, `must be >= ${minimum}`);
  if (maximum !== undefined && value > maximum) pushError(errors, path, `must be <= ${maximum}`);
}

function expectString(value: unknown, path: string, errors: string[], minLength = 0): value is string {
  if (typeof value !== "string") {
    pushError(errors, path, "must be a string");
    return false;
  }
  if (value.length < minLength) pushError(errors, path, `must be at least ${minLength} character(s)`);
  return true;
}

function expectArenaId(value: unknown, path: string, errors: string[]): void {
  if (!expectString(value, path, errors, 1)) return;
  if (value.length > 64 || !ARENA_ID.test(value)) pushError(errors, path, "must be an arena id");
}

function expectStateHash(value: unknown, path: string, errors: string[]): void {
  if (!expectString(value, path, errors, 1)) return;
  if (!STATE_HASH.test(value)) pushError(errors, path, "must match sha256:<64 hex chars>");
}

function expectDateTime(value: unknown, path: string, errors: string[]): void {
  if (!expectString(value, path, errors, 1)) return;
  if (!DATE_TIME.test(value) || Number.isNaN(Date.parse(value))) pushError(errors, path, "must be an ISO-8601 date-time");
}

function expectNullableString(value: unknown, path: string, errors: string[]): void {
  if (value !== null && typeof value !== "string") pushError(errors, path, "must be a string or null");
}

function expectObjectOrNull(value: unknown, path: string, errors: string[]): void {
  if (value !== null && !isRecord(value)) pushError(errors, path, "must be an object or null");
}

function validateModel(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, MODEL_KEYS, path, errors);
  if (!("provider" in value)) pushError(errors, `${path}.provider`, "is required");
  else expectString(value.provider, `${path}.provider`, errors, 1);
  if (!("name" in value)) pushError(errors, `${path}.name`, "is required");
  else expectString(value.name, `${path}.name`, errors, 1);
  if ("version" in value) expectString(value.version, `${path}.version`, errors, 1);
}

function validateSubject(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, SUBJECT_KEYS, path, errors);
  if (!("kind" in value)) pushError(errors, `${path}.kind`, "is required");
  else if (!SUBJECT_KINDS.has(value.kind as string)) pushError(errors, `${path}.kind`, "must be a subject kind");
  if (!("id" in value)) pushError(errors, `${path}.id`, "is required");
  else expectArenaId(value.id, `${path}.id`, errors);
}

function validateToolResult(value: unknown, path: string, errors: string[]): void {
  if (value === null) return;
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object or null");
    return;
  }
  if ("ok" in value && typeof value.ok !== "boolean") pushError(errors, `${path}.ok`, "must be a boolean");
  if ("latencyMs" in value) expectNumber(value.latencyMs, `${path}.latencyMs`, errors, 0);
  if ("queueMs" in value) expectNumber(value.queueMs, `${path}.queueMs`, errors, 0);
  if ("providerMs" in value) expectNumber(value.providerMs, `${path}.providerMs`, errors, 0);
  if ("roundMs" in value) expectNumber(value.roundMs, `${path}.roundMs`, errors, 0);
  if ("inputTokens" in value) expectNumber(value.inputTokens, `${path}.inputTokens`, errors, 0);
  if ("outputTokens" in value) expectNumber(value.outputTokens, `${path}.outputTokens`, errors, 0);
  if ("cachedInputTokens" in value) expectNumber(value.cachedInputTokens, `${path}.cachedInputTokens`, errors, 0);
  if ("finishReason" in value && value.finishReason !== undefined) expectString(value.finishReason, `${path}.finishReason`, errors, 1);
  const error = value.error;
  const errorIsObject = isRecord(error);
  if ("error" in value && error !== null && !errorIsObject) {
    pushError(errors, `${path}.error`, "must be an object or null");
  }
  if (errorIsObject) {
    extraKeys(error, ERROR_BODY_KEYS, `${path}.error`, errors);
    if (!("code" in error)) pushError(errors, `${path}.error.code`, "is required");
    else expectString(error.code, `${path}.error.code`, errors, 1);
    if (!("message" in error)) pushError(errors, `${path}.error.message`, "is required");
    else expectString(error.message, `${path}.error.message`, errors, 1);
    if ("retryable" in error && typeof error.retryable !== "boolean") {
      pushError(errors, `${path}.error.retryable`, "must be a boolean");
    }
  }
  if (value.ok === false && !errorIsObject) {
    pushError(errors, `${path}.error`, "is required when ok is false");
  }
  if (errorIsObject && value.ok !== false) {
    pushError(errors, `${path}.ok`, "must be false when error is present");
  }
}

function validateEvent(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, EVENT_KEYS, path, errors);
  for (const key of ["tick", "kind", "timestamp", "stateHash"] as const) {
    if (!(key in value)) pushError(errors, `${path}.${key}`, "is required");
  }
  if ("tick" in value) expectInteger(value.tick, `${path}.tick`, errors, 0);
  if ("kind" in value && !TRACE_EVENT_KINDS.has(value.kind as TraceEventKind)) {
    pushError(errors, `${path}.kind`, "must be a trace event kind");
  }
  if ("timestamp" in value) expectDateTime(value.timestamp, `${path}.timestamp`, errors);
  if ("stateHash" in value) expectStateHash(value.stateHash, `${path}.stateHash`, errors);
  if ("actorId" in value) expectArenaId(value.actorId, `${path}.actorId`, errors);
  if ("role" in value && !TRACE_ROLES.has(value.role as string)) pushError(errors, `${path}.role`, "must be a staff role");
  if ("targetRole" in value && !TRACE_ROLES.has(value.targetRole as string)) {
    pushError(errors, `${path}.targetRole`, "must be a staff role");
  }
  if ("checkpointId" in value) expectArenaId(value.checkpointId, `${path}.checkpointId`, errors);
  if ("model" in value) validateModel(value.model, `${path}.model`, errors);
  if ("requestId" in value) expectArenaId(value.requestId, `${path}.requestId`, errors);
  if ("idempotencyKey" in value) {
    if (!expectString(value.idempotencyKey, `${path}.idempotencyKey`, errors, 1)) {
      /* already recorded */
    } else if (value.idempotencyKey.length > 130 || !IDEMPOTENCY_KEY.test(value.idempotencyKey)) {
      pushError(errors, `${path}.idempotencyKey`, "must be an idempotency key");
    }
  }
  if ("text" in value) expectNullableString(value.text, `${path}.text`, errors);
  if ("observation" in value) expectObjectOrNull(value.observation, `${path}.observation`, errors);
  if ("action" in value) expectObjectOrNull(value.action, `${path}.action`, errors);
  if ("toolResult" in value) validateToolResult(value.toolResult, `${path}.toolResult`, errors);
  if ("outcome" in value) expectObjectOrNull(value.outcome, `${path}.outcome`, errors);
  if ("correctionRationale" in value) expectNullableString(value.correctionRationale, `${path}.correctionRationale`, errors);
  if ("correctionCategory" in value) {
    if (value.correctionCategory !== null && !CORRECTION_CATEGORIES.has(value.correctionCategory as string)) {
      pushError(errors, `${path}.correctionCategory`, "must be a correction category or null");
    }
  }
  if ("changedDecisionEventId" in value && value.changedDecisionEventId !== null) {
    expectArenaId(value.changedDecisionEventId, `${path}.changedDecisionEventId`, errors);
  }
  if ("probeEventId" in value && value.probeEventId !== null) {
    expectArenaId(value.probeEventId, `${path}.probeEventId`, errors);
  }
  if ("subject" in value) validateSubject(value.subject, `${path}.subject`, errors);
  if ("payload" in value) expectObjectOrNull(value.payload, `${path}.payload`, errors);
  if ("round" in value) expectInteger(value.round, `${path}.round`, errors, 1);
}

function validateActionEnvelope(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, ACTION_ENVELOPE_KEYS, path, errors);
  for (const key of ACTION_ENVELOPE_KEYS) {
    if (!(key in value)) pushError(errors, `${path}.${key}`, "is required");
  }
  if ("version" in value && value.version !== "restaurant-arena-action/v1") {
    pushError(errors, `${path}.version`, "must be restaurant-arena-action/v1");
  }
  if ("episodeId" in value) expectArenaId(value.episodeId, `${path}.episodeId`, errors);
  if ("actorId" in value) expectArenaId(value.actorId, `${path}.actorId`, errors);
  if ("actorType" in value && !ACTOR_TYPES.has(value.actorType as string)) {
    pushError(errors, `${path}.actorType`, "must be worker or player");
  }
  if ("role" in value && !TRACE_ROLES.has(value.role as string)) pushError(errors, `${path}.role`, "must be a staff role");
  if ("tool" in value && !ACTION_TOOLS.has(value.tool as string)) pushError(errors, `${path}.tool`, "must be a known tool");
  if ("arguments" in value && !isRecord(value.arguments)) pushError(errors, `${path}.arguments`, "must be an object");
  if ("tick" in value) expectInteger(value.tick, `${path}.tick`, errors, 0);
  if ("timestamp" in value) expectDateTime(value.timestamp, `${path}.timestamp`, errors);
  if ("requestId" in value) expectArenaId(value.requestId, `${path}.requestId`, errors);
  if ("idempotencyKey" in value) {
    if (!expectString(value.idempotencyKey, `${path}.idempotencyKey`, errors, 1)) {
      /* already recorded */
    } else if (value.idempotencyKey.length > 130 || !IDEMPOTENCY_KEY.test(value.idempotencyKey)) {
      pushError(errors, `${path}.idempotencyKey`, "must be an idempotency key");
    }
  }
}

function validateReplayInput(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  const kind = value.kind;
  if (kind === "step") {
    extraKeys(value, STEP_INPUT_KEYS, path, errors);
    if (!("action" in value)) pushError(errors, `${path}.action`, "is required");
    else expectString(value.action, `${path}.action`, errors, 1);
  } else if (kind === "time") {
    extraKeys(value, TIME_INPUT_KEYS, path, errors);
  } else if (kind === "envelope") {
    extraKeys(value, ENVELOPE_INPUT_KEYS, path, errors);
    if (!("envelope" in value)) pushError(errors, `${path}.envelope`, "is required");
    else validateActionEnvelope(value.envelope, `${path}.envelope`, errors);
    if ("telemetry" in value && !isRecord(value.telemetry)) pushError(errors, `${path}.telemetry`, "must be an object");
  } else if (kind === "controllers") {
    extraKeys(value, CONTROLLER_INPUT_KEYS, path, errors);
    if (!("roles" in value)) pushError(errors, `${path}.roles`, "is required");
    else if (!Array.isArray(value.roles)) pushError(errors, `${path}.roles`, "must be an array");
    else {
      const seen = new Set<string>();
      value.roles.forEach((role, index) => {
        if (!TRACE_ROLES.has(role as string)) pushError(errors, `${path}.roles[${index}]`, "must be a staff role");
        if (typeof role === "string") {
          if (seen.has(role)) pushError(errors, `${path}.roles[${index}]`, "must be unique");
          seen.add(role);
        }
      });
    }
  } else {
    pushError(errors, `${path}.kind`, "must be step, time, envelope, or controllers");
  }
  if (!("tick" in value)) pushError(errors, `${path}.tick`, "is required");
  else expectInteger(value.tick, `${path}.tick`, errors, 0);
  if (!("stateHash" in value)) pushError(errors, `${path}.stateHash`, "is required");
  else expectStateHash(value.stateHash, `${path}.stateHash`, errors);
  if ("restaurantStateHash" in value) expectStateHash(value.restaurantStateHash, `${path}.restaurantStateHash`, errors);
  if (!INPUT_KINDS.has(kind as string) && kind !== undefined && kind !== "step" && kind !== "time" && kind !== "envelope" && kind !== "controllers") {
    /* already recorded */
  }
}

function validateEpisode(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, EPISODE_KEYS, path, errors);
  for (const key of EPISODE_KEYS) {
    if (!(key in value)) pushError(errors, `${path}.${key}`, "is required");
  }
  if ("id" in value) expectArenaId(value.id, `${path}.id`, errors);
  if ("phase" in value && value.phase !== "active" && value.phase !== "complete") {
    pushError(errors, `${path}.phase`, "must be active or complete");
  }
  if ("tick" in value) expectInteger(value.tick, `${path}.tick`, errors, 0);
  if ("maxTicks" in value) expectInteger(value.maxTicks, `${path}.maxTicks`, errors, 1);
}

function validateClock(value: unknown, path: string, errors: string[]): void {
  if (!isRecord(value)) {
    pushError(errors, path, "must be an object");
    return;
  }
  extraKeys(value, CLOCK_KEYS, path, errors);
  if (!("minute" in value)) pushError(errors, `${path}.minute`, "is required");
