/**
 * Native replay of a restaurant-arena-trace-v3 record back into a live game.
 */

import { RestaurantGame, type ArenaInputRecord } from "./restaurant-game.js";
import { computeStateHash, type RestaurantArenaTraceV3 } from "./trace.js";

function canonicalizeWorkerIdentity(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalizeWorkerIdentity);
  if (typeof value !== "object" || value === null) return value;
  const record = value as Record<string, unknown>;
  const next: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(record)) {
    if (key === "role" && entry === "expediter") {
      next[key] = "supply_lead";
      continue;
    }
    if ((key === "id" || key === "actorId" || key === "to" || key === "workerId") && entry === "worker-expediter") {
      next[key] = "worker-supply_lead";
      continue;
    }
    if (key === "workerId" && entry === "expediter") {
      next[key] = "worker-supply_lead";
      continue;
    }
    if (key === "targetRole" && entry === "expediter") {
      next[key] = "supply_lead";
      continue;
    }
    next[key] = canonicalizeWorkerIdentity(entry);
  }
  return next;
}

function assertHashesMatch(expected: string, actual: string, message: string): void {
  if (expected !== actual) throw new Error(message);
}

/**
 * Apply one recorded replay input to a live game. Used by the overlay's
 * animated replay after `replayArenaTrace` has already verified the record.
 */
export function applyArenaReplayInput(game: RestaurantGame, input: ArenaInputRecord, index = 0): void {
  switch (input.kind) {
    case "step":
      game.step(input.action);
      break;
    case "time":
      game.advanceTime();
      break;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      break;
    case "controllers":
      game.setExternalControllers(input.roles);
      break;
    default:
      throw new Error(`unknown replay input kind at ${index}`);
  }
  assertHashesMatch(
    input.stateHash,
    computeStateHash(game.checkpointState()),
    `checkpoint mismatch at input ${index}`,
  );
  if (input.restaurantStateHash) {
    assertHashesMatch(
      input.restaurantStateHash,
      computeStateHash(game.state()),
      `checkpoint mismatch at input ${index}`,
    );
  }
}

/**
 * Rebuild a live RestaurantGame from a captured restaurant-arena-trace-v3
 * record. Throws if the recorded tick-0 state (after mapping the legacy
 * expediter roster onto supply_lead), any checkpoint hash, the final state
 * hash, or any part of the terminal record disagrees with native replay.
 */
export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  const game = new RestaurantGame(trace.seed, trace.replay.variation);
  const engineInitial = canonicalizeWorkerIdentity(game.getInitialState());
  const recordedInitial = canonicalizeWorkerIdentity(trace.initialState);
  assertHashesMatch(
    computeStateHash(engineInitial),
    computeStateHash(recordedInitial),
    "initial state mismatch",
  );

  for (const [index, input] of trace.replay.inputs.entries()) {
    applyArenaReplayInput(game, input, index);
  }

  assertHashesMatch(
    trace.replay.finalStateHash,
    computeStateHash(game.checkpointState()),
    "state hash mismatch",
  );
  if (trace.replay.finalRestaurantStateHash) {
    assertHashesMatch(
      trace.replay.finalRestaurantStateHash,
      computeStateHash(game.state()),
      "state hash mismatch",
    );
  }

  if (JSON.stringify(game.getTerminalStatus()) !== JSON.stringify(trace.terminal)) {
    throw new Error("terminal mismatch");
  }
  return game;
}

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import {
  canonicalJson,
  captureArenaTrace,
  exportTraceJson,
} from "../src/games/restaurant-arena/trace.js";

const ROOT = join(import.meta.dir, "..");
const FIXTURE_PATH = join(ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");
const BENCHMARK_SEED = 218220;
const BENCHMARK_START = "2026-09-05T18:00:00.000Z";
const BENCHMARK_EPISODE_ID = "dinner-rush-benchmark-218220";

function captureBenchmarkTrace() {
  const game = new RestaurantGame(BENCHMARK_SEED, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return captureArenaTrace(game, {
    runKind: "benchmark",
    episodeId: BENCHMARK_EPISODE_ID,
    startTime: BENCHMARK_START,
  });
}

const captured = captureBenchmarkTrace();
const encoded = exportTraceJson(captured);

if (process.argv.includes("--check")) {
  const disk = readFileSync(FIXTURE_PATH, "utf8");
  if (canonicalJson(captured) !== canonicalJson(JSON.parse(disk))) {
    console.error("Fixture is stale");
    process.exit(1);
  }
  console.log("Fixture is current");
} else {
  writeFileSync(FIXTURE_PATH, encoded);
  console.log(`Wrote ${FIXTURE_PATH}`);
}

import { readFileSync } from "node:fs";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";
import {
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

function loadTrace(path: string): unknown {
  const text = readFileSync(path, "utf8");
  if (path.endsWith(".jsonl")) {
    const lines = text.split(/\r?\n/).filter((line) => line.trim().length > 0);
    if (lines.length === 0) throw new Error("empty jsonl trace");
    const header = JSON.parse(lines[0]!);
    const events = lines.slice(1).map((line) => JSON.parse(line));
    return { ...header, events };
  }
  return JSON.parse(text);
}

const path = process.argv[2];
if (!path) {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(1);
}

try {
  const parsed = loadTrace(path);
  const validation = validateArenaTraceV3(parsed);
  if (!validation.valid) {
    console.error(validation.errors.join("\n"));
    process.exit(1);
  }
  replayArenaTrace(parsed as RestaurantArenaTraceV3);
  console.log("Native replay passed");
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
}

