import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { replayArenaTrace } from "./replay.js";
import { roundForTick } from "./rounds.js";
import {
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

function playShortShift(game = new RestaurantGame(218220)): RestaurantGame {
  game.step("sim_start");
  game.step("tick");
  game.step("tick");
  return game;
}

describe("restaurant-arena-trace-v3 capture", () => {
  it("exposes captureTrace as a thin wrapper around captureArenaTrace", () => {
    const game = playShortShift();
    const viaHelper = captureArenaTrace(game, { runKind: "live" });
    const viaMethod = game.captureTrace({ runKind: "live" });
    expect(viaMethod).toEqual(viaHelper);
    expect(viaMethod.terminal).toEqual(game.getTerminalStatus());
    expect(viaMethod.initialState).toEqual(game.getInitialState());
    expect(viaMethod.replay).toEqual(game.getReplayRecord());
  });

  it("requires runKind so live, synthetic and benchmark stays distinguishable", () => {
    const game = new RestaurantGame();
    expect(() => captureArenaTrace(game, {} as { runKind: "live" })).toThrow(/runKind/);
    expect(captureArenaTrace(game, { runKind: "synthetic" }).runKind).toBe("synthetic");
    expect(captureArenaTrace(game, { runKind: "benchmark" }).runKind).toBe("benchmark");
  });

  it("stamps additionalEvents with the round their tick falls in and merges them", () => {
    const game = playShortShift();
    const note: TraceV3Event = {
      tick: 2,
      kind: "message",
      timestamp: "2026-09-05T18:00:06.000Z",
      stateHash: "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
      actorId: "player",
      text: "out-of-band note",
    };
    const trace = captureArenaTrace(game, { runKind: "live", additionalEvents: [note] });
    const merged = trace.events.find((event) => event.text === "out-of-band note");
    expect(merged).toBeDefined();
    expect(merged!.round).toBe(roundForTick(2));
    expect(trace.events.map((event) => event.tick)).toEqual(
      [...trace.events].sort((left, right) => left.tick - right.tick).map((event) => event.tick),
    );
  });

  it("identifying the session a trace came from (#281)", () => {
    const game = playShortShift();
    const withoutSession = captureArenaTrace(game, { runKind: "live" });
    expect(withoutSession.sessionId).toBeUndefined();

    const first = captureArenaTrace(game, { runKind: "live", sessionId: "game_session-one" });
    const second = captureArenaTrace(game, { runKind: "live", sessionId: "game_session-two" });
    expect(first.episodeId).toBe(second.episodeId);
    expect(first.sessionId).not.toBe(second.sessionId);

    const valid = validateArenaTraceV3(first);
    expect(valid.valid).toBe(true);
    expect(valid.errors).toEqual([]);

    const malformed = validateArenaTraceV3({ ...first, sessionId: "bad session id" });
    expect(malformed.valid).toBe(false);
    expect(malformed.errors.some((error) => error.includes("sessionId"))).toBe(true);
  });
});

describe("restaurant-arena-trace-v3 export and validation", () => {
  it("exports schema-valid JSON and JSONL", () => {
    const game = playShortShift();
    const trace = captureArenaTrace(game, { runKind: "live" });
    const parsed = JSON.parse(exportTraceJson(trace));
    const validation = validateArenaTraceV3(parsed);
    expect(validation.valid).toBe(true);
    expect(validation.errors).toEqual([]);

    const jsonl = exportTraceJsonl(trace);
    const lines = jsonl.trim().split("\n");
    expect(lines.length).toBe(trace.events.length + 1);
    expect(JSON.parse(lines[0]!)).toMatchObject({ version: trace.version, replay: trace.replay });
  });

  it("rejects malformed records field by field", () => {
    const game = playShortShift();
    const trace = captureArenaTrace(game, { runKind: "live" });

    const missingKind = validateArenaTraceV3({ ...trace, runKind: undefined });
    expect(missingKind.valid).toBe(false);
    expect(missingKind.errors.some((error) => error.includes("runKind"))).toBe(true);

    const badHash = validateArenaTraceV3({
      ...trace,
      replay: { ...trace.replay, finalStateHash: "not-a-hash" },
    });
    expect(badHash.valid).toBe(false);
    expect(badHash.errors.some((error) => error.includes("finalStateHash"))).toBe(true);

    const extra = validateArenaTraceV3({ ...trace, notAField: true });
    expect(extra.valid).toBe(false);
    expect(extra.errors.some((error) => error.includes("notAField"))).toBe(true);

    const badTerminal = validateArenaTraceV3({
      ...trace,
      terminal: { ...trace.terminal, status: "won" },
    });
    expect(badTerminal.valid).toBe(false);
    expect(badTerminal.errors.some((error) => error.includes("terminal.status"))).toBe(true);
  });
});

describe("native replayArenaTrace", () => {
  it("rebuilds the live game and matches the recorded terminal", () => {
    const game = playShortShift();
    game.step("verify_substitution");
    const trace = game.captureTrace({ runKind: "live" });
    const replayed = replayArenaTrace(trace);
    expect(replayed).toBeInstanceOf(RestaurantGame);
    expect(replayed.getTerminalStatus()).toEqual(trace.terminal);
    expect(replayed.checkpointState()).toEqual(game.checkpointState());
  });

  it("throws when any part of the terminal record disagrees", () => {
    const game = playShortShift();
    const trace = game.captureTrace({ runKind: "live" });
    const tampered: RestaurantArenaTraceV3 = {
      ...trace,
      terminal: { ...trace.terminal, reason: "tampered" },
    };
    expect(() => replayArenaTrace(tampered)).toThrow(/terminal mismatch/);
  });

  it("throws when initialState is altered even if every field still parses", () => {
    const game = playShortShift();
    const trace = game.captureTrace({ runKind: "live" });
    const initialState = structuredClone(trace.initialState) as {
      outcomes: { cash: number };
    };
    initialState.outcomes.cash = 99;
    expect(() => replayArenaTrace({ ...trace, initialState })).toThrow(/initial state mismatch/);
  });

  it("replays a record that still names the legacy expediter worker", () => {
    const game = playShortShift();
    const trace = game.captureTrace({ runKind: "live" });
    const initialState = structuredClone(trace.initialState) as {
      workers: Array<{ id: string; role: string }>;
    };
    for (const worker of initialState.workers) {
      if (worker.role === "supply_lead") {
        worker.role = "expediter";
        worker.id = "worker-expediter";
      }
    }
    const replayed = replayArenaTrace({ ...trace, initialState });
    expect(replayed.getTerminalStatus()).toEqual(trace.terminal);
  });

  it("throws when a checkpoint hash disagrees", () => {
    const game = playShortShift();
    const trace = game.captureTrace({ runKind: "live" });
    const inputs = structuredClone(trace.replay.inputs);
    inputs[0] = {
      ...inputs[0]!,
      stateHash: "sha256:ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff",
    };
    expect(() => replayArenaTrace({ ...trace, replay: { ...trace.replay, inputs } })).toThrow(/checkpoint mismatch/);
  });
});

